package io.spring.application;

import io.spring.application.CursorPager.Direction;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
public class CursorPageParameter<T> {

    private static final int MAX_LIMIT = 1000;

    private int limit = 20;

    private T cursor;

    private Direction direction;

    public CursorPageParameter(T cursor, int limit, Direction direction) {
        setLimit(limit);
        setCursor(cursor);
        setDirection(direction);
    }

    public boolean isNext() {
        return direction == Direction.NEXT;
    }

    public int getQueryLimit() {
        return limit + 1;
    }

    private void setCursor(T cursor) {
        this.cursor = cursor;
    }

    private void setLimit(int limit) {
        if (limit > MAX_LIMIT) {
            this.limit = MAX_LIMIT;
        } else if (limit > 0) {
            this.limit = limit;
        }
    }
}

package io.spring.application;

import java.util.List;
import lombok.Getter;

@Getter
public class CursorPager<T extends Node> {

    private List<T> data;

    private boolean next;

    private boolean previous;

    public CursorPager(List<T> data, Direction direction, boolean hasExtra) {
        this.data = data;
        if (direction == Direction.NEXT) {
            this.previous = false;
            this.next = hasExtra;
        } else {
            this.next = false;
            this.previous = hasExtra;
        }
    }

    public boolean hasNext() {
        return next;
    }

    public boolean hasPrevious() {
        return previous;
    }

    public PageCursor getStartCursor() {
        return data.isEmpty() ? null : data.get(0).getCursor();
    }

    public PageCursor getEndCursor() {
        return data.isEmpty() ? null : data.get(data.size() - 1).getCursor();
    }

    public enum Direction {

        PREV, NEXT
    }
}

package io.spring.application;

import lombok.Data;
import lombok.NoArgsConstructor;

@NoArgsConstructor
@Data
public class Page {

    private static final int MAX_LIMIT = 100;

    private int offset = 0;

    private int limit = 20;

    public Page(int offset, int limit) {
        setOffset(offset);
        setLimit(limit);
    }

    private void setOffset(int offset) {
        if (offset > 0) {
            this.offset = offset;
        }
    }

    private void setLimit(int limit) {
        if (limit > MAX_LIMIT) {
            this.limit = MAX_LIMIT;
        } else if (limit > 0) {
            this.limit = limit;
        }
    }
}

